'use strict'

import soundManager from '../service/sound-manager'
import resource from '../resource'
import { overlaps } from '../utils/box'
import { TILE_WIDTH, TILE_HEIGHT, ITEM_RUPEE, ITEM_FIVE_RUPESS, ITEM_HEART, ITEM_FAIRY, ITEM_CLOCK, ITEM_BOMB, ENEMY_OCTOROK_RED, ENEMY_OCTOROK_RED_FAST, ENEMY_OCTOROK_BLUE, ENEMY_OCTOROK_BLUE_FAST, ENEMY_MOBLIN_RED, ENEMY_MOBLIN_BLUE, ENEMY_LYNEL_BLUE, ENEMY_TEKTITE_RED, ENEMY_TEKTITE_BLUE, ENEMY_LEEVER_RED, ENEMY_LEEVER_BLUE, ENEMY_GHINI, SOUND_GET_HEART, SOUND_GET_ITEM, SOUND_GET_RUPEE } from '../constant'

// What a dead enemy leaves, as in the ROM (bank 4, $B06A; see docs/rom-analysis.md). Each type of
// enemy is in one of 4 classes; a class has its chance of leaving something (out of 256) and its row
// of 10 items. A counter going round the 10 columns at every death picks the item of the row
const CLASSES = {
  [ENEMY_OCTOROK_RED]: 0,
  [ENEMY_OCTOROK_RED_FAST]: 0,
  [ENEMY_TEKTITE_RED]: 0,
  [ENEMY_MOBLIN_RED]: 0,
  [ENEMY_LEEVER_BLUE]: 0,
  [ENEMY_GHINI]: 1,
  [ENEMY_TEKTITE_BLUE]: 1,
  [ENEMY_LEEVER_RED]: 1,
  [ENEMY_OCTOROK_BLUE]: 2,
  [ENEMY_OCTOROK_BLUE_FAST]: 2,
  [ENEMY_MOBLIN_BLUE]: 2,
  [ENEMY_LYNEL_BLUE]: 2
}
const OTHER_CLASS = 3
const CHANCES = [0x50, 0x98, 0x68, 0x68]
const R = ITEM_RUPEE
const R5 = ITEM_FIVE_RUPESS
const H = ITEM_HEART
const F = ITEM_FAIRY
const C = ITEM_CLOCK
const B = ITEM_BOMB
const ROWS = [
  [H, R, H, R, F, R, H, H, R, R],
  [R5, R, H, R, R5, H, C, R, R, R],
  [H, B, R, C, R, H, B, R, B, H],
  [H, H, F, R, H, F, H, H, H, R]
]
// Kills in a row without Link being hurt: the 16th leaves a fairy, every 10th five rupees
const FAIRY_KILLS = 16
const SERIES_KILLS = 10

// What Link killed lately, counted as the original does
export function createKillRecord () {
  return { kills: 0, series: 0, column: 0 }
}

// Link hurt: the kills in a row start again
export function breakKillSeries (record) {
  record.kills = 0
  record.series = 0
}

// The item a dying enemy leaves, undefined for none; counts the kill
export function chooseDrop (type, record, random = Math.random, byBomb = false) {
  record.kills++
  record.series = Math.min(record.series + 1, SERIES_KILLS)
  const column = record.column
  record.column = (record.column + 1) % ROWS[0].length

  if (record.kills === FAIRY_KILLS) {
    return ITEM_FAIRY
  }
  if (record.series >= SERIES_KILLS) {
    // A bomb instead when the 10th was killed by a bomb
    record.series = 0
    return byBomb ? ITEM_BOMB : ITEM_FIVE_RUPESS
  }
  const dropClass = CLASSES[type] ?? OTHER_CLASS
  if (Math.floor(random() * 256) >= CHANCES[dropClass]) {
    return undefined
  }

  return ROWS[dropClass][column]
}

// On the ground for 255 × 2 frames, then gone
export const DROP_STEPS = 510
const FRAME_STEPS = 8
// The fairy flies about, changing its way now and then
const FAIRY_SPEED = 1
const FAIRY_MIN_TURN_STEPS = 16
const FAIRY_MAX_TURN_STEPS = 48
// Items are 8 NES pixels wide, in the middle of their tile
const ITEM_INSET_X = 8

export class Drop {
  constructor (name, x, y, random = Math.random) {
    this.name = name
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.random = random
    this.steps = 0
    this.done = false
    this.vector = [0, 0]
    this.turnSteps = 0
  }

  getBox () {
    return { x: this.x + ITEM_INSET_X, y: this.y, width: this.width - 2 * ITEM_INSET_X, height: this.height }
  }

  fly (map) {
    if (this.turnSteps <= 0) {
      const angle = Math.floor(this.random() * 8) * Math.PI / 4
      this.vector = [Math.round(Math.cos(angle)), Math.round(Math.sin(angle))]
      this.turnSteps = FAIRY_MIN_TURN_STEPS + Math.floor(this.random() * (FAIRY_MAX_TURN_STEPS - FAIRY_MIN_TURN_STEPS + 1))
    }
    this.turnSteps--
    // Back from the edges of the screen
    const [dx, dy] = this.vector
    if (this.x + dx * FAIRY_SPEED < map.x || this.x + this.width + dx * FAIRY_SPEED > map.x + map.width) {
      this.vector[0] = -dx
    }
    if (this.y + dy * FAIRY_SPEED < map.y || this.y + this.height + dy * FAIRY_SPEED > map.y + map.height) {
      this.vector[1] = -dy
    }
    this.x += this.vector[0] * FAIRY_SPEED
    this.y += this.vector[1] * FAIRY_SPEED
  }

  // What the item does to Link and the screen
  give (map, link) {
    const inventory = link.inventory
    switch (this.name) {
      case ITEM_RUPEE:
        inventory.rupees = Math.min(inventory.maxRupees, inventory.rupees + 1)
        soundManager.play(resource.getSound(SOUND_GET_RUPEE))
        break
      case ITEM_FIVE_RUPESS:
        inventory.rupees = Math.min(inventory.maxRupees, inventory.rupees + 5)
        soundManager.play(resource.getSound(SOUND_GET_RUPEE))
        break
      case ITEM_HEART:
        link.currentLife = Math.min(link.totalLife, link.currentLife + 1)
        soundManager.play(resource.getSound(SOUND_GET_HEART))
        break
      case ITEM_FAIRY:
        link.currentLife = Math.min(link.totalLife, link.currentLife + 3)
        soundManager.play(resource.getSound(SOUND_GET_HEART))
        break
      case ITEM_BOMB:
        link.addBombs(4)
        soundManager.play(resource.getSound(SOUND_GET_ITEM))
        break
      case ITEM_CLOCK:
        // The enemies of the screen stand still and harmless until Link leaves it
        map.frozen = true
        soundManager.play(resource.getSound(SOUND_GET_ITEM))
        break
    }
  }

  // Picked by Link or his sword
  process (map, link) {
    // Already given (brought back by the boomerang)
    if (this.done) {
      return
    }
    this.steps++
    if (this.steps >= DROP_STEPS) {
      this.done = true
      return
    }
    if (this.name === ITEM_FAIRY) {
      this.fly(map)
    }
    const box = this.getBox()
    const swordBox = link.getSwordBox()
    if (overlaps(box, link.getBodyBox()) || (swordBox && overlaps(box, swordBox))) {
      this.give(map, link)
      this.done = true
    }
  }

  draw (context) {
    const sprite = resource.getSprite(`item_${this.name}`)
    const index = Math.floor(this.steps / FRAME_STEPS) % (sprite?.images.length || 1)
    sprite?.images[index]?.draw(context, this.x, this.y, this.width, this.height)
  }
}
