'use strict'

import soundManager from '../service/sound-manager'
import clock from '../service/clock'
import hitboxManager from '../service/hitbox-manager'
import resource from '../resource'
import { UNIQUE_ITEMS, LINK_ACTION_MOVE, SOUND_FANFARE, LINK_ACTION_PICK, SOUND_TEXT_LOOP, SOUND_OVERWORLD, DIRECTION_EAST, DIRECTION_WEST, TRANSITION_MAP_HORIZONTAL_STEP, TRANSITION_MAP_HORIZONTAL_INTERVAL, TRANSITION_MAP_VERTICAL_STEP, TRANSITION_MAP_VERTICAL_INTERVAL, DIRECTION_SOUTH, SOUND_STAIRS, SOUND_LINK_DIE, TILE_WIDTH, TILE_HEIGHT, DIRECTION_NORTH, CAVE_GIFT, RUPEE_COUNT_INTERVAL, DOOR_REPAIR_PRICE } from '../constant'
import { drawMoneyGame, formatSigned } from './cave'
import { INVINCIBLE_STEPS } from './link'

class CaveEntrance {
  async play (link) {
    return new Promise((resolve) => {
      link.y += TILE_HEIGHT
      const limitY = link.y - 3 * TILE_HEIGHT
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        link.y -= 2
        if (link.y <= limitY) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, 15)
    })
  }
}

class CaveExit {
  async play (link, currentMap) {
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        link.y += 2
        if (link.y > currentMap.y + currentMap.height) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, 15)
    })
  }
}

// How far from the stairs Link may still be when he goes down them: his center entering the tile is not
// enough (walking sideways along the wall below a cave door, half of him overlaps the door)
const STAIRS_ALIGNMENT_TOLERANCE = TILE_WIDTH / 4

class CaveStairsDown {
  canStart (link, tile) {
    return Math.abs(link.x - tile.x) <= STAIRS_ALIGNMENT_TOLERANCE && Math.abs(link.y - tile.y) <= STAIRS_ALIGNMENT_TOLERANCE
  }

  async play (link) {
    return new Promise((resolve) => {
      soundManager.stop(resource.getSound(SOUND_OVERWORLD))
      soundManager.play(resource.getSound(SOUND_STAIRS))
      link.direction = DIRECTION_NORTH
      const tile = link.tile
      link.clipY = 0
      link.startWalking()
      const transitionTimer = clock.repeat(() => {
        // Link slides onto the stairs while he goes down instead of jumping onto them
        link.x += Math.sign(tile.x - link.x)
        link.y += Math.sign(tile.y - link.y)
        link.clipY++
        if (link.clipY >= TILE_HEIGHT) {
          transitionTimer.cancel()
          link.clipY = 0
          link.stopWalking()
          resolve()
        }
      }, 30)
    })
  }
}

class CaveStairsUp {
  async play (link) {
    return new Promise((resolve) => {
      soundManager.play(resource.getSound(SOUND_STAIRS))
      link.direction = DIRECTION_SOUTH
      link.clipY = TILE_HEIGHT
      link.startWalking()
      const transitionTimer = clock.repeat(() => {
        link.clipY--
        if (link.clipY <= 0) {
          transitionTimer.cancel()
          link.clipY = 0
          link.stopWalking()
          soundManager.play(resource.getSound(SOUND_OVERWORLD))
          resolve()
        }
      }, 30)
    })
  }
}

// Direction in which Link crosses to the next screen
const MAP_DRAG_VECTORS = {
  [DIRECTION_EAST]: [1, 0],
  [DIRECTION_NORTH]: [0, -1],
  [DIRECTION_SOUTH]: [0, 1],
  [DIRECTION_WEST]: [-1, 0]
}

class MapDrag {
  // Both maps scroll by exactly one screen while Link walks from the edge he leaves to the opposite
  // edge of the next screen. The last step is left on display (maps scrolled, Link in the coordinates of
  // the screen he leaves): until the game switches maps, the frames drawn show the next screen in
  // place, and the game resets the offsets when it switches (see Game.process). A screen that is not the
  // next one (the whirlwind of the whistle) is shifted by targetShift to come in its place
  async play (link, currentMap, targetMap, targetShift = { x: 0, y: 0 }) {
    const [dx, dy] = MAP_DRAG_VECTORS[link.direction]
    const horizontal = dx !== 0
    const sign = dx + dy
    const distance = horizontal ? currentMap.width : currentMap.height
    const linkSize = horizontal ? link.width : link.height
    const linkFrom = sign > 0 ? distance - linkSize : 0
    const linkTo = distance - linkSize - linkFrom
    const step = horizontal ? TRANSITION_MAP_HORIZONTAL_STEP : TRANSITION_MAP_VERTICAL_STEP
    const interval = horizontal ? TRANSITION_MAP_HORIZONTAL_INTERVAL : TRANSITION_MAP_VERTICAL_INTERVAL
    const nbTicks = Math.round(distance / step)

    let tick = 0
    const update = () => {
      const progress = tick / nbTicks
      const offset = -sign * distance * progress
      const linkPosition = linkFrom + (linkTo - linkFrom) * progress
      if (horizontal) {
        currentMap.offsetX = offset
        targetMap.offsetX = targetShift.x + offset
        targetMap.offsetY = targetShift.y
        link.x = currentMap.x + linkPosition
      } else {
        currentMap.offsetY = offset
        targetMap.offsetY = targetShift.y + offset
        targetMap.offsetX = targetShift.x
        link.y = currentMap.y + linkPosition
      }
    }

    update()
    link.startWalking()
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        tick++
        update()
        if (tick >= nbTicks) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, interval)
    })
  }
}

// Rupees counted one at a time, up or down, between 0 and what the wallet holds; Link goes on meanwhile
function countRupees (link, delta) {
  let left = Math.abs(delta)
  if (left === 0) {
    return
  }
  const step = Math.sign(delta)
  const timer = clock.repeat(() => {
    link.inventory.rupees = Math.max(0, Math.min(link.inventory.maxRupees, link.inventory.rupees + step))
    left--
    if (left === 0) {
      timer.cancel()
    }
  }, RUPEE_COUNT_INTERVAL)
}

// The rupee of a secret cave: the moblin stays, the amount shows under the rupee, nothing is held up
class SecretRupees {
  play (link, item) {
    countRupees(link, item.rupees)
    item.pickable = false
    item.label = item.rupees.toString()
    link.map.emptied = true
  }
}

// The door repair: Link pays as he comes in (all he has if it is not enough, measured in the ROM), once
class DoorRepair {
  play (link) {
    countRupees(link, -Math.min(DOOR_REPAIR_PRICE, link.inventory.rupees))
    link.map.emptied = true
  }
}

// The money making game: every rupee shows what it hid, Link gets or loses what is under his
class MoneyGame {
  play (link, item, random) {
    const values = drawMoneyGame(random)
    link.map.items.forEach((other, i) => {
      other.pickable = false
      other.label = formatSigned(values[i])
    })
    countRupees(link, values[link.map.items.indexOf(item)])
  }
}

// Pay to talk: the prices go, the rupees stay, and what Link paid decides the answer
class PayToTalk {
  play (link, item) {
    countRupees(link, -item.price)
    for (const other of link.map.items) {
      other.pickable = false
      other.label = undefined
    }
    link.map.character?.say(item.text ?? '')
  }
}

class ItemPick {
  buy (link, item) {
    countRupees(link, -item.price)
  }

  removeItemFromMap (map, item) {
    const index = map.items.indexOf(item)
    if (index > -1) {
      map.items.splice(index, 1)
    }
  }

  addItemToMap (map, item) {
    map.items.push(item)
  }

  play (link, item) {
    if (item.price) {
      this.buy(link, item)
    }

    if (link.map.character) {
      link.map.character.vanish(1300)
    }

    const clonedItem = item.clone()
    clonedItem.price = undefined
    clonedItem.label = undefined
    for (const i of link.map.items) {
      i.enabled = false
    }

    // Test picking item or not
    /* if (false) {
      this.finalizeTransition(link.map, item)
      return
    } */

    link.stopWalking()
    link.action = LINK_ACTION_PICK
    this.addItemToMap(link.map, clonedItem)

    const itemCenterX = hitboxManager.getHorizontalCenter(clonedItem.hitbox)
    const itemDeltaX = itemCenterX - clonedItem.x
    clonedItem.x = link.x - itemDeltaX + 4
    clonedItem.y = link.y - clonedItem.height
    soundManager.play(resource.getSound(SOUND_FANFARE))

    const self = this
    return new Promise((resolve) => {
      clock.delay(() => {
        link.action = LINK_ACTION_MOVE
        self.removeItemFromMap(link.map, clonedItem)
        self.finalizeTransition(link, item)
        resolve()
      }, 1300)
    })
  }

  finalizeTransition (link, item) {
    link.pickItem(item)
    // Taken once: the cave is empty from then on
    if (UNIQUE_ITEMS.includes(item.name) || link.map.cave === CAVE_GIFT) {
      link.map.emptied = true
      link.map.items = []
      link.map.characters = []
    }
  }
}

class Dialog {
  async play (link) {
    let length = 0
    soundManager.play(resource.getSound(SOUND_TEXT_LOOP))
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        length++
        link.map.character.displayedText = link.map.character.text.substring(0, length)
        if (link.map.character.displayedText === link.map.character.text) {
          soundManager.stop(resource.getSound(SOUND_TEXT_LOOP))
          transitionTimer.cancel()
          resolve()
        }
      }, 50)
    })
  }
}

// Death of Link, measured in the ROM (in frames, 60 per second, from the fatal hit)
const FRAME = 1000 / 60
// Link flashes as when he is hurt, still on the screen as it was
const DEATH_FLASH_FRAMES = 34
const DEATH_RED_FRAME = 62
// Then he spins, a quarter turn every 5 frames, 4 times round, to face down again
const DEATH_SPIN_ORDER = [DIRECTION_SOUTH, DIRECTION_EAST, DIRECTION_NORTH, DIRECTION_WEST]
const DEATH_SPIN_FRAMES = 5
const DEATH_SPIN_TURNS = 16
// The scenery darkens (see death-colours.js), the frames each step starts at
const DEATH_DARKEN_FRAMES = [141, 151, 161, 171]
const DEATH_GREY_FRAME = 172
// His sparkle (sprite link_death): 10 frames, then 4
const DEATH_SPARKLE_FRAMES = [196, 206]
const DEATH_HIDDEN_FRAME = 210
const DEATH_GAME_OVER_FRAME = 256
const DEATH_END_FRAME = 351

function wait (duration) {
  return new Promise((resolve) => clock.delay(resolve, duration))
}

// The screen freezes, the enemies vanish and the music stops. Link flashes, the scenery turns red and Link spins,
// the scenery darkens to black, Link turns grey, becomes a sparkle and vanishes, then GAME OVER. The steps are
// published in game.deathEffect, which Game.draw follows (palette: step of the colours of the scenery)
class Death {
  async play (game) {
    const link = game.link
    soundManager.stop(resource.getSound(SOUND_OVERWORLD))
    soundManager.play(resource.getSound(SOUND_LINK_DIE))
    game.map.clearEnemies()
    link.knockback = undefined
    link.usingItem = false
    link.stillSteps = 0
    link.poseSteps = 0
    link.action = LINK_ACTION_MOVE
    link.standStill()

    const effect = { palette: undefined, grey: false, sparkleFrame: undefined, hidden: false, gameOver: false }
    game.deathEffect = effect
    // Each step at its frame from the fatal hit (waits that follow one another would drift)
    const start = clock.now
    const until = (frame) => wait(start + frame * FRAME - clock.now)

    link.invincibleSteps = INVINCIBLE_STEPS
    const flashTimer = clock.repeat(() => { link.invincibleSteps-- }, FRAME)
    await until(DEATH_FLASH_FRAMES)
    flashTimer.cancel()
    link.invincibleSteps = 0

    await until(DEATH_RED_FRAME)
    effect.palette = 0
    link.direction = DIRECTION_SOUTH
    for (let turn = 1; turn <= DEATH_SPIN_TURNS; turn++) {
      await until(DEATH_RED_FRAME + 1 + (turn - 1) * DEATH_SPIN_FRAMES)
      link.direction = DEATH_SPIN_ORDER[turn % DEATH_SPIN_ORDER.length]
    }

    for (const [step, start] of DEATH_DARKEN_FRAMES.entries()) {
      await until(start)
      effect.palette = step + 1
    }
    await until(DEATH_GREY_FRAME)
    effect.grey = true
    link.dead = true

    for (const [sparkleFrame, start] of DEATH_SPARKLE_FRAMES.entries()) {
      await until(start)
      effect.sparkleFrame = sparkleFrame
    }
    await until(DEATH_HIDDEN_FRAME)
    effect.sparkleFrame = undefined
    effect.hidden = true

    await until(DEATH_GAME_OVER_FRAME)
    effect.gameOver = true
    await until(DEATH_END_FRAME)
  }
}

export { CaveEntrance, CaveExit, CaveStairsDown, CaveStairsUp, MapDrag, Dialog, ItemPick, SecretRupees, DoorRepair, MoneyGame, PayToTalk, Death }
